import Foundation
import Testing
@testable import RAKit

/// Decodes the golden frames generated by the Go server (protocol/fixtures).
struct FixtureTests {
    static let dir = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().appending(path: "../../../../protocol/fixtures").standardized

    func load(_ name: String) throws -> Data {
        try Data(contentsOf: Self.dir.appending(path: name))
    }

    struct Notification<P: Decodable>: Decodable { var method: String; var params: P }
    struct EventsParams: Decodable { var stream: String; var events: [Event] }
    struct Response<R: Decodable>: Decodable { var id: JSONValue; var result: R?; var error: RPCError? }

    @Test func sessionEvents() throws {
        let n = try WireCoding.decoder().decode(Notification<EventsParams>.self, from: load("notification_events_session.json"))
        #expect(n.method == "events")
        #expect(n.params.events.count == 14)
        let session = try #require(n.params.events[0].session)
        #expect(session.status == .awaitingApproval)
        #expect(session.workspace.kind == .worktree)
        #expect(session.workspace.agentPath == "/w/s1/.claude/worktrees/fix")
        #expect(session.hasDraft)
        let turn = try #require(n.params.events[1].turn)
        #expect(turn.usage?.costUsd == 0.0123)
        let items = n.params.events.compactMap(\.item)
        #expect(items.count == 11)
        #expect(items.map(\.kind) == [.userMessage, .reasoning, .toolCall, .assistantMessage, .approval, .approval, .approval, .plan, .notice, .error, .assistantMessage])
        #expect(items[0].images?.first?.mimeType == "image/png")
        #expect(items[0].images?.first?.aspectRatio == 1170.0 / 2532.0)
        #expect(items[2].images?.first?.width == nil)  // WebP: no dimensions
        #expect(items[2].images?.first?.aspectRatio == nil)
        #expect(items[2].tool?.input?["command"]?.stringValue == "go test ./...")
        #expect(items[2].tool?.exitCode == 0)
        // A reply links to the images it shows as rad-image:<id>.
        let shown = try #require(items[3].images?.first)
        #expect(items[3].text?.hasSuffix("![Screenshot](rad-image:\(shown.id))") == true)
        #expect(ImageRef.id(linkedBy: try #require(URL(string: "rad-image:\(shown.id)"))) == shown.id)
        #expect(ImageRef.id(linkedBy: try #require(URL(string: "https://example.com/a.png"))) == nil)
        #expect(items[4].approval?.options.map(\.kind) == [.allowOnce, .allowSession, .deny])
        #expect(items[5].approval?.special == .question)
        #expect(items[5].approval?.decision?.answers?["Which DB?"] == "SQLite")
        #expect(items[5].approval?.questions?.map(\.optionsOnly) == [nil, true])
        #expect(items[6].approval?.special == .plan)
        #expect(items[7].plan?.entries?.count == 2)
        #expect(items[10].parentItemId == "i3")
        // Unknown event types decode without payload instead of failing the batch.
        #expect(n.params.events.last?.type == "future.event")
    }

    @Test func indexEvents() throws {
        let n = try WireCoding.decoder().decode(Notification<EventsParams>.self, from: load("notification_events_index.json"))
        #expect(n.params.events.map(\.type) == ["project.upserted", "session.upserted", "project.removed"])
        #expect(n.params.events[0].project?.isGitRepo == true)
        #expect(n.params.events[1].session?.draft?.images?.first?.width == 800)
        #expect(n.params.events[2].id == "p0")
    }

    @Test func responses() throws {
        let dec = WireCoding.decoder()
        struct Commands: Decodable { var commands: [SlashCommand] }
        let commands = try dec.decode(Response<Commands>.self, from: load("response_session_commands.json")).result?.commands ?? []
        #expect(commands.map(\.prompt) == ["/compact", "/skill:prototype"])
        #expect(commands.last?.kind == "skill")
        #expect(commands.last?.scope == "user")
        #expect(commands.last?.description == "Prototype to answer a design question")

        struct Harnesses: Decodable { var harnesses: [HarnessInfo] }
        let h = try dec.decode(Response<Harnesses>.self, from: load("response_harness_list.json"))
        #expect(h.result?.harnesses.count == 2)
        #expect(h.result?.harnesses[0].usable == true)
        #expect(h.result?.harnesses[1].usable == false)
        #expect(h.result?.harnesses[1].hint?.isEmpty == false)
        // A model's own efforts replace the harness's; others get the default model's.
        let claude = h.result?.harnesses[0]
        #expect(claude?.efforts(forModel: "sonnet").map(\.id) == ["low", "high"])
        #expect(claude?.efforts(forModel: nil).map(\.id) == ["low", "medium", "high"])
        #expect(h.result?.harnesses[1].efforts(forModel: nil).isEmpty == true)
        #expect(claude?.commands?.map(\.prompt) == ["/compact"])
        #expect(claude?.commands?.first?.description?.isEmpty == false)
        #expect(h.result?.harnesses[1].commands == nil)
        #expect(claude?.caps.update == true && claude?.caps.login == true && claude?.caps.oneShot == true)
        #expect(claude?.caps.steer == true)
        #expect(h.result?.harnesses[1].caps.update == nil)
        #expect(h.result?.harnesses[1].caps.steer == nil)

        let d = try dec.decode(Response<Diff>.self, from: load("response_diff.json"))
        #expect(d.result?.files.map(\.status) == [.modified, .renamed, .added])
        #expect(d.result?.files[2].binary == true)

        let fs = try dec.decode(Response<FSListing>.self, from: load("response_fs_list.json"))
        #expect(fs.result?.entries.count == 2)

        let e = try dec.decode(Response<Empty>.self, from: load("response_error.json"))
        #expect(e.error?.code == "conflict")

        let s = try dec.decode(Response<Session>.self, from: load("response_session.json"))
        #expect(s.result?.title == "Fix the tests")
        #expect(s.result?.context?.fraction == 0.26)
        #expect(s.result?.modelName(in: nil) == "Sonnet 5.5")
        #expect(s.result?.modelInfo?.effort == "high")
        #expect(s.result?.effort == "high")
        #expect(s.result?.backgroundTasks?.map(\.kind) == [.command, .agent])
        #expect(s.result?.backgroundTasks?.first?.description == "Watch the release run")
        #expect(s.result?.isUnread == true)
        #expect(s.result?.draft?.text == "Then update the changelog")
        #expect(s.result?.draft?.images?.map(\.mimeType) == ["image/jpeg"])
        #expect(s.result?.forkedFrom?.sessionId == "s0")
        #expect(s.result?.forkedFrom?.turn == 3)

        let p = try dec.decode(PairResult.self, from: load("http_pair_response.json"))
        #expect(p.token == "0123abcd")

        let info = try dec.decode(Response<ServerInfo>.self, from: load("response_server_info.json"))
        #expect(info.result?.terminal == true)
        #expect(info.result?.drafts == true)
        #expect(info.result?.forks == true)
        #expect(info.result?.commit == true)
        #expect(info.result?.deviceId == "dev1")
    }

    @Test func terminalMessages() throws {
        let dec = WireCoding.decoder()
        let a = try dec.decode(TerminalMessage.self, from: load("terminal_attached.json"))
        #expect(a.type == "attached" && a.reset == true && a.offset == 262130 && a.cols == 80 && a.id?.isEmpty == false)
        let r = try dec.decode(TerminalMessage.self, from: load("terminal_resize.json"))
        #expect(r == TerminalMessage(type: "resize", cols: 120, rows: 40))
        // What a client sends encodes as the server's fixture does.
        let sent = try dec.decode(TerminalMessage.self, from: try WireCoding.encoder().encode(TerminalMessage(type: "resize", cols: 120, rows: 40)))
        #expect(sent == r)
        #expect(try dec.decode(TerminalMessage.self, from: load("terminal_exit.json")).exitCode == 129)
        let e = try dec.decode(TerminalMessage.self, from: load("terminal_error.json"))
        #expect(e.code == "gone" && e.message?.isEmpty == false)
    }

    @Test func terminalQuery() {
        func q(_ items: [URLQueryItem]) -> String { items.map { "\($0.name)=\($0.value ?? "")" }.joined(separator: "&") }
        #expect(q(TerminalSession.query(sessionID: "s1", cols: 80, rows: 24, create: true, shellID: nil, offset: 0))
                == "session=s1&cols=80&rows=24&create=1")
        #expect(q(TerminalSession.query(sessionID: "s1", cols: 100, rows: 30, create: false, shellID: "ab", offset: 4096))
                == "session=s1&cols=100&rows=30&id=ab&offset=4096")
    }

    @Test func serverManagement() throws {
        let dec = WireCoding.decoder()
        let settings = try dec.decode(Response<ServerSettings>.self, from: load("response_server_settings.json"))
        #expect(settings.result?.systemAgent == SystemAgent(harness: "claude", model: "haiku", effort: "low"))

        let update = try #require(try dec.decode(Response<UpdateInfo>.self, from: load("response_check_update.json")).result)
        #expect(update.current == "0.11.0" && update.latest == "0.12.0" && update.available && update.via == "app")
        #expect(update.installable && update.busy == ["Fix the tests"] && update.reason == nil)

        let task = try #require(try dec.decode(Response<ServerTask>.self, from: load("response_task.json")).result)
        #expect(task.kind == .login && task.harness == "claude" && task.status == .running && task.isRunning)
        #expect(task.input == true && task.url == "https://claude.com/cai/oauth/authorize?code=true")
        #expect(task.output.hasSuffix("Paste code here if prompted >") && task.endedAt == nil)

        struct Tasks: Decodable { var tasks: [ServerTask] }
        let list = try #require(try dec.decode(Response<Tasks>.self, from: load("response_task_list.json")).result)
        #expect(list.tasks.map(\.kind) == [.updateAgent, .updateServer])
        #expect(list.tasks.map(\.status) == [.succeeded, .failed])
        #expect(list.tasks[0].version == "0.164.0" && list.tasks[0].endedAt != nil)
        #expect(list.tasks[1].error?.contains("checksum") == true && list.tasks[1].harness == nil)
        #expect(list.tasks.allSatisfy { $0.sessionId == nil && $0.steps == nil })
    }

    @Test func commits() throws {
        let dec = WireCoding.decoder()
        let p = try #require(try dec.decode(Response<CommitPreview>.self, from: load("response_commit_preview.json")).result)
        #expect(p.branch == "ra/fix-tests" && p.remote == "origin" && p.base == "main" && p.ahead == 1)
        #expect(p.files.map(\.path) == ["api_test.go", "notes.md"])
        #expect(p.files.map(\.status) == [.modified, .added])
        #expect(p.files[0].additions == 4 && p.files[0].deletions == 1)
        #expect(p.message.hasPrefix("Fix the flaky tests\n\n"))

        let task = try #require(try dec.decode(Response<ServerTask>.self, from: load("response_task_commit.json")).result)
        #expect(task.kind == .commit && task.sessionId == "s1" && task.status == .succeeded && task.harness == nil)
        #expect(task.steps?.map(\.id) == ["commit", "push", "pull_request"])
        #expect(task.steps?.map(\.status) == [.skipped, .succeeded, .succeeded])
        #expect(task.steps?[0].detail == "Nothing to commit")
        #expect(task.steps?[2].title == "Open a pull request" && task.steps?[2].detail == "#12 Fix the flaky tests")
        #expect(task.url == "https://github.com/me/app/pull/12")

        // A step status from a newer server reads as pending.
        let step = try dec.decode(ServerTask.Step.self, from: Data(#"{"id":"x","title":"X","status":"waiting"}"#.utf8))
        #expect(step.status == .pending && step.detail == nil)
    }
}
